BEGIN TRANSACTION;
CREATE TABLE Departments (
    DepartmentID INT PRIMARY KEY,
    DepartmentName VARCHAR(100),
    FactoryCode VARCHAR(50)
);
CREATE TABLE DowntimeEvents (
    EventID INTEGER PRIMARY KEY,
    MachineID INT,
    Category VARCHAR(100),
    DurationMinutes REAL,
    Shift VARCHAR(50),
    EventDate TEXT,
    LossType VARCHAR(100),
    FOREIGN KEY (MachineID) REFERENCES Machines(MachineID)
);
CREATE TABLE EnergyMeterReadings (
    ID INTEGER PRIMARY KEY,
    NodeID VARCHAR(100),
    TagName VARCHAR(100),
    NodeValue REAL,
    Timestamp TEXT,
    LocalTimestamp TEXT,
    CreatedOn TEXT
);
CREATE TABLE EnergyMeterTags (
    ID INTEGER PRIMARY KEY,
    TagName VARCHAR(100),
    IsSubscripedTag INT,
    EnergyMeterID INT,
    EnergyMeterTagCategoryID INT,
    NodeID VARCHAR(100),
    FOREIGN KEY (EnergyMeterID) REFERENCES EnergyMeters(EnergyID)
);
CREATE TABLE EnergyMeters (
    ID INTEGER PRIMARY KEY,
    EnergyID INT UNIQUE,
    EnergyName VARCHAR(100),
    DepartmentID INT,
    ParentID INT,
    ModelName VARCHAR(50),
    ManualURL VARCHAR(255),
    MeterType VARCHAR(50),
    FOREIGN KEY (DepartmentID) REFERENCES Departments(DepartmentID)
);
CREATE TABLE Machines (
    MachineID INTEGER PRIMARY KEY,
    MachineName VARCHAR(100),
    DepartmentID INT,
    FactoryCode VARCHAR(50),
    EnergyMeterID INT
);
COMMIT;
